const { localidades, categorias } = $input.item.json

const combos = []
for (const localidad of localidades) {
  for (const cat of categorias) {
    combos.push({
      json: {
        localidad,
        categoria: cat.nombre,
        nicho:     cat.nicho,
        query:     `${cat.nombre} ${localidad}`,
      }
    })
  }
}
return combos
